using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Temporal;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
public sealed class AstronomySeasonalPatternValidationRule:TemporalRuleBase{public const string Id="temporal.seasonal.policy"; public override string RuleId=>Id; public override int Order=>800; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var s=p.Pattern.Season; if(s is null) yield break; var start=s.Start.Month*100+s.Start.Day; var end=s.End.Month*100+s.End.Day; if(!s.CrossesYearBoundary&&start>end) yield return Issue(AstronomyTemporalValidationCodes.SeasonalOrderingInvalid,"Non-wrapping seasonal pattern start cannot be after end.","$.pattern.season",RuleId); if(s.CrossesYearBoundary&&start<=end) yield return Issue(AstronomyTemporalValidationCodes.SeasonalOrderingInvalid,"Wrapping seasonal pattern must cross the year boundary.","$.pattern.season",RuleId);}}
